4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\NormalizesPerPage;
7	use App\Models\Retail\CommissionPayout;
8	use App\Services\Stripe\CommissionPayoutService;
9	use Illuminate\Http\JsonResponse;
10	use Illuminate\Http\Request;
11	use Illuminate\Support\Facades\DB;
12	use Stripe\Exception\ApiConnectionException;
13	use Stripe\Exception\RateLimitException;
14	
15	// V2: Staff-admin controls for commission payouts. Today only exposes manual
16	// retry — the daily ProcessCommissionPayoutsJob handles normal flow and the
17	// Phase 1 pending sweep auto-retries pending batches. This endpoint exists
18	// for stuck `failed` batches, which the sweep intentionally does NOT pick up
19	// (to avoid re-triggering a card decline loop). Support uses this after
20	// fixing the underlying issue (brand updated their card, affiliate completed
21	// Stripe Connect onboarding, etc.).
22	class StaffCommissionPayoutController extends ApiController
23	{
24	    use NormalizesPerPage;
25	
26	    public function __construct(
27	        private readonly CommissionPayoutService $payoutService,
28	    ) {}
29	
30	    /**
31	     * GET /staff/commission-payouts
32	     *
33	     * List all payouts platform-wide. Query params: status (pending|processing|completed|failed|...), per_page (default 25, max 100).
34	     */
35	    public function index(Request $request): JsonResponse
36	    {
37	        $perPage = $this->normalizePerPage($request, 25, 100);
38	        $status = $request->query('status');
39	
40	        $query = DB::table('commerce.commission_payouts')->orderByDesc('created_at');
41	
42	        if (is_string($status) && $status !== '') {
43	            $query->where('status', $status);
44	        }
45	
46	        return $this->paginated($query->paginate($perPage));
47	    }
48	
49	    /**
50	     * POST /staff/commission-payouts/{payout}/retry
51	     *
52	     * Manually retry a stuck payout batch. Only `failed` and `pending` batches
53	     * are retryable — `completed` / `collecting` / `collected` / `transferring`
54	     * return 422.
55	     *
56	     * The retry runs synchronously: by the time the response comes back, the
57	     * batch has either completed, moved back to pending (with a new failure
58	     * code), or failed again. The refreshed state is in the response so staff
59	     * can see what happened without a second request.
60	     *
61	     * @return JsonResponse {
62	     *                      data: {
63	     *                      id: string,
64	     *                      status: 'completed'|'pending'|'failed'|...,
65	     *                      failure_code: string|null,
66	     *                      failure_reason: string|null,
67	     *                      processed_at: string|null,
68	     *                      net_payout_cents: int,
69	     *                      currency_code: string
70	     *                      }
71	     *                      }
72	     */
73	    public function retry(Request $request, CommissionPayout $payout): JsonResponse
74	    {
75	        if (! in_array($payout->status, ['failed', 'pending'], true)) {
76	            return $this->error(
77	                "Payout is in status '{$payout->status}' and cannot be retried. Only 'failed' or 'pending' batches are retryable.",
78	                422
79	            );
80	        }
81	
82	        // retryPayout() resets status, clears failure_code/reason, and runs
83	        // processPayoutBatch synchronously. Transient Stripe errors re-throw
84	        // (Horizon backoff design) — surface them as 503 so staff know to retry.
85	        try {
86	            $this->payoutService->retryPayout($payout);
87	        } catch (ApiConnectionException|RateLimitException $e) {
88	            return $this->error('Stripe is temporarily unavailable. Please try again in a moment.', 503);
89	        }
90	        $payout->refresh();
91	
92	        return $this->success([
93	            'id' => $payout->id,
94	            'status' => $payout->status,
95	            'failure_code' => $payout->failure_code,
96	            'failure_reason' => $payout->failure_reason,
97	            'processed_at' => $payout->processed_at?->toIso8601String(),
98	            'net_payout_cents' => (int) $payout->net_payout_cents,
99	            'currency_code' => (string) $payout->currency_code,
100	        ]);
101	    }
102	}
